import re

def parse_price(s: str) -> float | None:
    if not isinstance(s, str):
        return None
    text = s.strip()
    if not text:
        return None

    lower = text.lower()
    if lower.startswith('gratis'):
        return 0.0
    if lower.startswith('bieden'):
        return None

    # Strip currency symbol/code and whitespace
    text = text.replace('€', '')
    text = re.sub(r'eur', '', text, flags=re.IGNORECASE)
    text = re.sub(r'\s+', '', text)

    # Dutch ',-' means no cents
    text = text.replace(',-', '')
    # Dutch thousands separator '.'
    text = text.replace('.', '')
    # Dutch decimal separator ','
    text = text.replace(',', '.')

    if not text:
        return None
    try:
        return float(text)
    except ValueError:
        return None

