_POSTCODE_RE = re.compile(r'^[1-9][0-9]{3}(?: )?[A-Za-z]{2}$')
_INVALID_LETTERS = {'SA', 'SD', 'SS'}

def is_valid_postcode(s: str) -> bool:
    if not isinstance(s, str):
        return False
    if not _POSTCODE_RE.fullmatch(s):
        return False
    return s[-2:].upper() not in _INVALID_LETTERS

