def dedupe(listings: list[dict]) -> list[dict]:
    best = {}
    for i, item in enumerate(listings):
        key = (' '.join(item['title'].split()).lower(), item['price'])
        cur = best.get(key)
        if cur is None:
            best[key] = (item['date'], i, item)
        elif item['date'] < cur[0]:
            best[key] = (item['date'], i, item)
    selected = sorted(best.values(), key=lambda t: t[1])
    return [item for _, _, item in selected]

